type StaticInvokeHybridPolicy struct {
	// W3C SCXML 5.10: Session ID
	SessionID string
	// ── SCE Accepted Subset §2.15: the datamodel="sce-static" variables ──
	// W3C SCXML 5.2: the `pick` datamodel variable.
	vPick string
	// W3C SCXML 5.2: the `base` datamodel variable.
	vBase uint32
	// W3C SCXML 5.2: the `enabled` datamodel variable.
	vEnabled bool
	// W3C SCXML 5.2: the `completed` datamodel variable, published (`sce:direction="out"`).
	vCompleted uint32
	// W3C SCXML 5.2: the `errors` datamodel variable, published (`sce:direction="out"`).
	vErrors uint32
	pendingInvokes []sce.PendingInvoke[StaticInvokeHybridState]
	activeInvokes  map[string]*sce.ChildSession
	childFirstRun sce.ChildEngine
	pendingDoneInvokeFirstRun bool
	childSecondRun sce.ChildEngine
	pendingDoneInvokeSecondRun bool
	childLossyRun sce.ChildEngine
	pendingDoneInvokeLossyRun bool
	childMissingRun sce.ChildEngine
	pendingDoneInvokeMissingRun bool
	// docs/adr/0045: how many times 'first_run' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsFirstRun uint64
	// docs/adr/0045: how many times 'second_run' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsSecondRun uint64
	// docs/adr/0045: how many times 'lossy_run' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsLossyRun uint64
	// docs/adr/0045: how many times 'missing_run' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsMissingRun uint64
	// W3C SCXML 6.4: Parent communication (unbounded — see sce.ParentEventQueue)
	ParentExternalQueue *sce.ParentEventQueue
	InvokeID           string
	ChildSessionID     string
	// §scxml-6.4.3: invoke param VALUES staged by the parent, applied after
	// this machine's datamodel init so they override its `<data>` defaults.
	pendingParams      map[string]interface{}
}

// NewStaticInvokeHybridPolicy creates a new policy with default values.
func NewStaticInvokeHybridPolicy() StaticInvokeHybridPolicy {
	return StaticInvokeHybridPolicy{
		// docs/adr/0045: a session has an id, which a saved state names it by. A
		// host that has one for it gives it with SetSessionID before it starts the
		// machine; a child's is its parent's and the id it was started under.
		SessionID: sce.DrawSessionID(),
		vPick: "file:static_hybrid_first.scxml",
		vBase: 4,
		vEnabled: true,
		vCompleted: 0,
		vErrors: 0,
		pendingInvokes: make([]sce.PendingInvoke[StaticInvokeHybridState], 0),
		activeInvokes:  make(map[string]*sce.ChildSession),
	}
}

